commands.command:
set -eu
wt=/Users/michal/agent-workspace/repos/photomap/worktrees/macbook-trackpad-zoom
cd "$wt"
test "$(git rev-parse HEAD)" = 6d08908929d643f10bf58488f8b8382ba325659e
for p in 8000 5174 18080 15174; do
 if lsof -nP -iTCP:"$p" -sTCP:LISTEN 2>/dev/null | grep -q LISTEN; then echo "PORT_BUSY_ABORT=$p"; exit 3; fi
done
test -f backend/data/app.db
backend/.venv/bin/python - <<'PY'
import sqlite3
db=sqlite3.connect('file:backend/data/app.db?mode=ro',uri=True)
cnt=db.execute("SELECT COUNT(*) FROM place WHERE status='published'").fetchone()[0]
print('TEST_MAP_PUBLISHED_PLACES',cnt)
assert cnt>=100
PY
cleanup(){ ./scripts/devctl.sh stop >/dev/null 2>&1 || true; }
trap cleanup EXIT
make start
cd frontend
node <<'JS'
const {chromium}=require('@playwright/test');
const assert=require('node:assert/strict');
(async () => {
const browser=await chromium.launch({executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome', headless:true});
try{
 const page=await browser.newPage({viewport:{width:1360,height:850}});
 await page.addInitScript(()=> {
  localStorage.setItem('photomap-public-map-tour-v3-complete','1');
  localStorage.setItem('photomap:moderator-recruitment:v1','dismissed');
 });
 const errors=[];
 page.on('pageerror',e=>errors.push(e.message));
 await page.goto('http://127.0.0.1:5174/',{waitUntil:'domcontentloaded'});
 await page.locator('.place-photo-marker').first().waitFor({timeout:20000});
 await page.waitForTimeout(300);
 const result=await page.evaluate(async()=>{
  const el=document.querySelector('.place-map');
  if(!el||!el.__photomapDebugMap)throw new Error('Map debug hook unavailable');
  const map=el.__photomapDebugMap, r=el.getBoundingClientRect();
  let ends=0;map.on('zoomend',()=>ends++);
  const emit=(delta,ctrl=false) => {
   el.dispatchEvent(new WheelEvent('wheel',{bubbles:true,cancelable:true,deltaMode:0,deltaY:delta,ctrlKey:ctrl,clientX:r.x+r.width/2,clientY:r.y+r.height/2}));
  };
  const initial=map.getZoom();
  const countStart=document.querySelectorAll('.place-photo-marker').length;
  for(let i=0;i<40;i++)emit(8);
  await new Promise(resolve=>setTimeout(resolve,650));
  const afterOut=map.getZoom(),endsOut=ends;
  for(let i=0;i<40;i++)emit(-8);
  await new Promise(resolve=>setTimeout(resolve,650));
  return {initial,afterOut,afterIn:map.getZoom(),endsOut,endsTotal:ends,countStart,countEnd:document.querySelectorAll('.place-photo-marker').length};
 });
 console.log('REAL_120_PLACE_MAP_STRESS',JSON.stringify(result));
 console.log('BROWSER_ERRORS',JSON.stringify(errors));
 assert(result.countStart>=5,'not enough visible markers for stress');
 assert(result.afterOut<result.initial-1,'40x8 outward zoom should progress');
 assert(result.afterIn>result.afterOut+1,'40x8 inward zoom should progress');
 assert(result.endsOut<=2,'too many final zoom events on outward gesture');
 assert(result.endsTotal<=4,'too many final zoom events total');
 assert.deepEqual(errors,[]);
}finally{await browser.close()}
})().catch(e=>{console.error(e);process.exitCode=1});
JS
cd "$wt"
cleanup
trap - EXIT
printf 'POST_STRESS_GIT_STATUS\n'
git status --short
echo PHOTOMAP_ZOOM_REALISTIC_STRESS_PASS
